local config = {
  ui_story_31120101_1_dialog_content = "(Aku sedang sangat kesal, dan inilah alasannya...)",
  ui_story_31120101_2_dialog_content = "(Lalim, dingin, tidak berperasaan, berbuat apa pun sesuka hati tanpa memedulikan orang lain...)",
  ui_story_31120101_2X_dialog_content = "(Kamu bisa menulis novel dengan semua sifat negatif yang menggambarkan dirinya.)",
  ui_story_31120101_3_dialog_content = "Sejak Smokey mulai tinggal di Colossus, pendapat semua orang tentangnya berangsur-angsur memburuk.",
  ui_story_31120101_4_dialog_content = "Banyak yang mengeluhkannya akhir-akhir ini karena sifatnya yang pemarah.",
  ui_story_31120101_5_dialog_content = "Kamu benar, bahkan Soroz telah melaporkannya karena meninggalkan jejak kaki gosong di mana-mana. Ini juga sangat sulit bagi Colossus kita yang tersayang.",
  ui_story_31120101_6_dialog_content = "Untuk mengatasi masalah ini, beberapa orang telah mengajukan solusi.",
  ui_story_31120101_7_dialog_content = "I-itu saranku... Aku menyebutnya \"Operasi: Peningkatan Citra Smokey\"!",
  ui_story_31120101_8_dialog_content = "A-aku akan berterima kasih atas bantuan apa pun yang bisa kamu berikan padaku.",
  ui_story_31120101_9_dialog_content = "Smokey mungkin terlihat sangat jahat, tetapi sebenarnya dia sangat baik.",
  ui_story_31120101_10_dialog_content = "Itu sebabnya aku ingin membantu semua orang memahami sisi baiknya juga...",
  ui_story_31120101_11_dialog_content = "Mungkin juga kita bisa dengan lembut mengingatkan dia untuk mencoba bergaul dengan semua orang di Colossus?",
  ui_story_31120101_12_dialog_content = "A-aku lebih muda darinya, jadi sepertinya aku tidak berhak melakukan itu! Tapi, karena PlayerName bertanggung jawab atas Colossus...",
  ui_story_31120101_13_dialog_content = "Kalau begitu, sepertinya bagian dari misi ini adalah tanggung jawabmu, PlayerName!",
  ui_story_31120101_14_dialog_content = "Areia dan aku akan memberikan dukungan secara rahasia. Smokey seharusnya ada di Cafe. Pergilah!",
  ui_story_31120101_15_dialog_content = "Eh? S-sekarang juga? Tapi, aku masih belum tahu apa yang harus kulakukan!",
  ui_story_31120101_15X_dialog_content = "Tidak apa-apa, kami memercayaimu. Pergilah sekarang!",
  ui_story_31120101_16_dialog_content = "<color=#e8d9bb>Hiss... Hiss...</color>",
  ui_story_31120101_17_dialog_content = "<size=30>Lagi-lagi dia... Lihat, lantainya kini terbakar...</size>",
  ui_story_31120101_18_dialog_content = "Minggir sana! Kecuali jika kamu ingin terbakar di bawah kakiku, menjauhlah dari pandanganku.",
  ui_story_31120101_19_dialog_content = "Hei, lihat apa kamu, PlayerName? Memangnya tidak ada yang perlu kamu kerjakan?",
  ui_story_31120101_20_dialog_content = "T-tidak ada, Smokey! Jangan pedulikan aku, aku kemari hanya untuk beristirahat...",
  ui_story_31120101_21_dialog_content = "Ehem... Permisi, Smokey? Bisakah kamu membantuku melakukan sesuatu?",
  ui_story_31120101_22_dialog_content = "(Aku mengerti... Dia mencoba menunjukkan kepada semua orang cara mendekati Smokey!)",
  ui_story_31120101_23_dialog_content = "(Selama dia setuju untuk membantu, aku bisa memujinya karena telah membantu! Lalu semua akan...)",
  ui_story_31120101_24_dialog_content = "Tidak.",
  ui_story_31120101_25_dialog_content = "Eh? T-tidak bisa? Maksudku, ini mungkin tidak terlalu merepotkan, jadi kenapa tidak dengarkan Vice dulu?",
  ui_story_31120101_26_dialog_content = "Cepat katakan. Aku sedang sibuk.",
  ui_story_31120101_27_dialog_content = "S-sebenarnya, ini untuk Areia, bukan untukku. Kalian berdua cukup dekat, 'kan?",
  ui_story_31120101_28_dialog_content = "Smokey? Bisakah kamu membantuku membawa beberapa bunga ke Lounge? Aku ingin...",
  ui_story_31120101_29_dialog_content = "(Tunggu... Aku sekarang paham strategi mereka! Dengan dalih membantu, mereka sebenarnya menyuruhnya mendekorasi Lounge dengan bunga!)",
  ui_story_31120101_30_dialog_content = "(Nantinya, jika ada yang menanyakannya, mereka akan tahu bahwa Smokey yang menaruh bunga-bunga itu di sana!)",
  ui_story_31120101_31_dialog_content = "(Ini agak kekanak-kanakan... Tapi, ini sesuai dengan rencana Areia. Selama Smokey setuju...)",
  ui_story_31120101_32_dialog_content = "Tidak. Aku punya pekerjaan lain, Areia.",
  ui_story_31120101_33_dialog_content = "Ehem... Kurasa Areia tidak bermaksud memintamu membantu sekarang juga, melainkan saat kau punya waktu luang...",
  ui_story_31120101_34_dialog_content = "Karena kau punya begitu banyak hal untuk dikatakan, PlayerName, bagaimana kalau kau bantu saja mereka? Mengantarkan bunga bukan keahlianku.",
  ui_story_31120101_35_dialog_content = "<size=30>Itu sedikit berlebihan, tahu... Bagaimana bisa seseorang bersikap begitu dingin...</size>",
  ui_story_31120101_36_dialog_content = "<size=30>Ssst, jangan keras-keras! Ayo kita pergi...</size>",
  ui_story_31120101_37_dialog_content = "Tapi kau sudah cukup lama duduk-duduk di Cafe ini, Smokey. Kukira kau tidak sibuk...",
  ui_story_31120101_38_dialog_content = "Jangan berasumsi.",
  ui_story_31120101_39_dialog_content = "B-baik. Maaf...",
  ui_story_31120101_39X1_dialog_content = "Kalau begitu, aku takkan mengganggumu lagi... <size=30>Semoga berhasil, PlayerName</size>. Dah...",
  ui_story_31120101_39X2_dialog_content = "...",
  ui_story_31120101_40_option_content = "(Aku harus jujur padanya tentang segalanya...)",
  ui_story_31120101_41_dialog_content = "Smokey... Kamu membuat semua orang takut di Cafe. Mereka mulai mengeluhkan perilakumu...",
  ui_story_31120101_41X_dialog_content = "<size=30>Sejujurnya, kami hanya mencoba membantumu meningkatkan citra dirimu...</size>",
  ui_story_31120101_42_option_content = "(Aku harus memikirkan pendekatan lain...)",
  ui_story_31120101_43_dialog_content = "Seharusnya kamu tidak menolak Areia seperti itu, Smokey. Aku rasa kamu menyakiti perasaannya...",
  ui_story_31120101_44_dialog_content = "Kamu ini memang tidak punya kegiatan lain, ya?",
  ui_story_31120101_45_dialog_content = "Bukan begitu, kebetulan aku sedang punya waktu luang...",
  ui_story_31120101_46_dialog_content = "Baiklah, karena kamu tidak punya kegiatan yang lebih baik, maka ikutlah denganku!",
  ui_story_31120101_47_dialog_content = "Eh? Tapi, aku belum selesai bicara... H-hei! Lepaskan kerahku! Kita mau ke mana?!",
  ui_story_31120101_48_dialog_content = "Umbraton! Berburu harta karun!",
  ui_story_31120101_49_dialog_content = "*Batuk-batuk* Kamu... Kamu hampir mencekikku sampai mati...",
  ui_story_31120101_50_dialog_content = "Berhenti bereaksi berlebihan. Sekarang, atur napasmu, lalu tenangkan diri.",
  ui_story_31120101_51_dialog_content = "Aku... Aku tidak perlu mengatur napasku... andai tidak ada seseorang yang mencekikku di sepanjang perjalanan ke sini...",
  ui_story_31120101_52_dialog_content = "Baiklah, astaga. Sudah baikan? Menurutmu, kamu masih bisa lanjut?",
  ui_story_31120101_53_dialog_content = "Ya, aku baik-baik saja sekarang... Tapi, bisakah kamu memberitahuku kenapa kamu menyeretku ke sini?",
  ui_story_31120101_54_dialog_content = "Tunggu.",
  ui_story_31120101_55_dialog_content = "Apa...? Jika kamu menyeret seseorang ke sini, setidaknya berikan alasannya...",
  ui_story_31120101_56_dialog_content = "Diam. Tunggu sebentar.",
  ui_story_31120101_57_dialog_content = "Smokey! Itu Smokey! Sedang apa kamu di sini?",
  ui_story_31120101_58_dialog_content = "Hanya lewat saja.",
  ui_story_31120101_58X_dialog_content = "Lihat, Smokey! Aku memetik beberapa bunga tadi! Ini, ambil satu!",
  ui_story_31120101_58X1_dialog_content = "Aku tidak mau bunga.",
  ui_story_31120101_59_dialog_content = "Ah... B-baiklah, kalau begitu...",
  ui_story_31120101_60_dialog_content = "Dia tampak terluka, Smokey... Kenapa tidak kamu ambil saja? Itu hanya bunga...",
  ui_story_31120101_61_dialog_content = "Tidak bisa. Aku punya urusan lain. Ayo, PlayerName.",
  ui_story_31120101_61X_dialog_content = "Hei, jangan pergi terlalu larut, nanti ibumu khawatir.",
  ui_story_31120101_62_dialog_content = "B-baiklah, Smokey. Sampai nanti!",
  ui_story_31120101_63_dialog_content = "Seharusnya ada beberapa Eclipsite yang mengintai di sekitar sini. Temukan mereka.",
  ui_story_31120101_64_dialog_content = "Hah?",
  ui_story_31120101_65_dialog_content = "Apakah aku kurang jelas? Kamu memiliki kemampuan psikis, 'kan? Katakan, bisakah kamu merasakan Eclipsite di sekitarmu dan, jika ya, di mana mereka?",
  ui_story_31120101_66_dialog_content = "Eclipsite... Sepertinya ada beberapa dari arah sana.",
  ui_story_31120101_67_dialog_content = "Bagus, ayo pergi!",
  ui_story_31120101_68_dialog_content = "Hah?! J-jangan tarik kerahku lagi!",
  ui_story_31120101_69_dialog_content = "Mereka ada di depan. Kita akan baik-baik saja, selama kita tidak langsung menyerang mereka.",
  ui_story_31120101_70_dialog_content = "Bagus. Sebagai hadiahmu, beri tahu aku tentang apa yang kalian bertiga rencanakan.",
  ui_story_31120101_71_dialog_content = "Yang di Cafe tadi... Sebenarnya apa tujuannya?",
  ui_story_31120101_72_dialog_content = "Jadi, kamu sudah tahu, ya? Sebenarnya, sejak kedatanganmu ke Colossus...",
  ui_story_31120101_73_dialog_content = "Sebagian besar orang mendapat kesan buruk tentangmu, tetapi Areia bersikeras bahwa kamu adalah orang yang baik.",
  ui_story_31120101_74_dialog_content = "Dia ingin semua orang menyadarinya juga... Jadi, dia meminta bantuan Vice dan aku untuk memperbaiki citra dirimu.",
  ui_story_31120101_75_dialog_content = "Hah! Apakah menjadi orang baik itu penting bagi semua orang? Baiklah, aku tidak akan bersikap keras lagi kepada mereka.",
  ui_story_31120101_76_dialog_content = "Kami hanya ingin membantumu bergaul dengan semua orang...",
  ui_story_31120101_76X_dialog_content = "Hmm. Setidaknya aku bisa membedakan antara diperlakukan seperti manusia dan diperlakukan seperti Eclipsite.",
  ui_story_31120101_76X1_dialog_content = "A-apa maksudmu?! Setiap orang bisa membedakannya, bukan?",
  ui_story_31120101_76X2_dialog_content = "Aku rasa kamu tidak memahami inti dari ide Areia...",
  ui_story_31120101_77_dialog_content = "Tidak, aku mengerti dengan baik. Aku menunggumu begitu lama, tetapi ternyata selama ini kamu merencanakan sesuatu?",
  ui_story_31120101_78_dialog_content = "Eh... Wajahmu tidak terlihat seperti orang yang mengerti...",
  ui_story_31120101_78X_dialog_content = "Selain itu, aku tidak ingat pernah setuju untuk menemuimu hari ini.",
  ui_story_31120101_79_dialog_content = "Memang tidak. Aku datang mencarimu untuk mengajakmu keluar berburu Eclipsite.",
  ui_story_31120101_79X_dialog_content = "Kamu tampak sangat sibuk, jadi aku menunggu sepanjang hari untuk menemuimu saat kamu beristirahat.",
  ui_story_31120101_80_dialog_content = "Gaaah!",
  ui_story_31120101_81_dialog_content = "Karena kami sudah ketahuan, tampaknya aku harus membuat kalian tahu diri! Kemarilah!",
  ui_story_31120101_82_dialog_content = "Graagh!",
  ui_story_31120101_83_dialog_content = "Cih... Di sini tidak ada juga.",
  ui_story_31120101_84_dialog_content = "Kita pindah ke titik berikutnya, PlayerName. Di manakah Eclipsite lainnya?",
  ui_story_31120101_85_dialog_content = "Sebenarnya apa yang kamu lakukan, Smokey?",
  ui_story_31120101_86_dialog_content = "Mencari kalung. Kalungnya jatuh di tengah gerombolan Eclipsite!",
  ui_story_31120101_87_dialog_content = "Mencari kalung... Apakah itu yang kamu maksud dengan \"punya urusan lain\"?",
  ui_story_31120101_88_dialog_content = "Sekarang kamu paham. Ayo, temukan titik kita berikutnya!",
  ui_story_31120101_89_dialog_content = "Baiklah! Berhentilah menarik kerahku...",
  ui_story_31120101_90_dialog_content = "Graagh!",
  ui_story_31120101_91_dialog_content = "Aku tidak punya waktu seharian, jadi maju sini, semuanya.",
  ui_story_31120101_92_dialog_content = "*Meraung*",
  ui_story_31120101_92X_dialog_content = "Sudahlah, diam!",
  ui_story_31120101_93_dialog_content = "Aduh...",
  ui_story_31120101_94_dialog_content = "Aduh, di sini juga tidak ada!",
  ui_story_31120101_95_option_content = "Kamu benar-benar kuat...",
  ui_story_31120101_96_dialog_content = "Apa? Kamu takut atau apa?",
  ui_story_31120101_97_dialog_content = "Sama sekali tidak! Sebenarnya, aku merasa sangat aman.",
  ui_story_31120101_98_dialog_content = "Hah, itu baru pemikiran yang menarik. Sayang sekali orang lain tidak merasakan hal yang sama, ya?",
  ui_story_31120101_99_option_content = "Sepatumu terbakar...",
  ui_story_31120101_100_dialog_content = "Apa? Ada masalah dengan itu?",
  ui_story_31120101_101_dialog_content = "Yah, semacam itu... Kudengar kamu meninggalkan bekas gosong di seluruh Colossus...",
  ui_story_31120101_102_dialog_content = "Apakah kondisi sepatumu masih bagus?",
  ui_story_31120101_103_dialog_content = "Hah, itu baru pertanyaan yang menarik. Tenang, sepatu ini terbuat dari material khusus.",
  ui_story_31120101_104_dialog_content = "Kamu pikir itu alasan aku tidak bisa bergaul dengan yang lain?",
  ui_story_31120101_105_dialog_content = "K-kenapa kamu tiba-tiba menanyakan itu?",
  ui_story_31120101_106_dialog_content = "Kamu pikir aku mungkin tahu jawaban untuk pertanyaan itu, ya?",
  ui_story_31120101_106X_dialog_content = "Silakan, beri tahu aku: kenapa aku sulit bergaul?",
  ui_story_31120101_107_dialog_content = "Baiklah...",
  ui_story_31120101_108_option_content = "Bagian terbesarnya adalah temperamenmu, kamu mudah marah!",
  ui_story_31120101_109_dialog_content = "Oh? Maksudmu seperti INI?",
  ui_story_31120101_110_option_content = "Hal terbesarnya adalah kamu tidak mudah didekati.",
  ui_story_31120101_111_dialog_content = "Oh? Bagaimana dengan ini? Masih berpikir aku tidak bisa didekati?",
  ui_story_31120101_112_dialog_content = "A-api?!",
  ui_story_31120101_113_dialog_content = "Tenang, apinya tidak akan membakarmu! <size=40>Merunduk!</size>",
  ui_story_31120101_114_dialog_content = "*Meraung*",
  ui_story_31120101_115_dialog_content = "Serangan diam-diam, ya? Jangan main-main, dasar pengecut.",
  ui_story_31120101_116_dialog_content = "M-maaf... Aku tidak memperhatikan.",
  ui_story_31120101_117_dialog_content = "Tidak apa-apa.",
  ui_story_31120101_117X_dialog_content = "Ha, ketemu!",
  ui_story_31120101_117X1_dialog_content = "Ayo, kita kembali.",
  ui_story_31120101_118_dialog_content = "Smokey? Sedang apa kamu di sini?",
  ui_story_31120101_119_dialog_content = "Ini, ini milik ibumu. Jaga baik-baik, jangan sampai hilang lagi.",
  ui_story_31120101_120_dialog_content = "Ini... kalung ibu! Smokey, bagaimana kamu...",
  ui_story_31120101_121_dialog_content = "Aku menemukannya tergeletak di jalan.",
  ui_story_31120101_122_dialog_content = "Terima kasih banyak, Smokey! Tapi, apa yang harus kuberikan kepadamu...",
  ui_story_31120101_123_dialog_content = "Tadi kamu punya bunga untukku, 'kan? Sini, berikan.",
  ui_story_31120101_124_dialog_content = "<size=30>Kamu tidak hanya mengambil bunga yang tadi, kamu juga memberinya kesempatan untuk membalas budi...</size>",
  ui_story_31120101_124X_dialog_content = "<size=30>Kamu sangat perhatian... Tapi, kenapa kamu meminta bunga itu seperti merampok!?</size>",
  ui_story_31120101_125_dialog_content = "Begitulah caraku melakukan sesuatu.",
  ui_story_31120101_126_dialog_content = "Terima kasih banyak, Smokey! Terimalah, aku memetik bunga ini pada pagi hari. Memang tidak sesegar tadi, tetapi kalau dipegang erat-erat, wanginya luar biasa!",
  ui_story_31120101_126X_dialog_content = "Mau mampir sekalian minum dulu?",
  ui_story_31120101_126X1_dialog_content = "Ibu akan segera pulang, dan aku yakin dia ingin mengucapkan terima kasih secara langsung!",
  ui_story_31120101_127_dialog_content = "Pegang ini, PlayerName.",
  ui_story_31120101_127X_dialog_content = "Kami pergi dulu, ya. Sampai nanti.",
  ui_story_31120101_128_dialog_content = "Hah? Baiklah... Dah, Smokey!",
  ui_story_31120101_129_dialog_content = "Eh? T-tunggu, Smokey! Kamu tidak bisa pergi begitu saja... Smokey?",
  ui_story_31120101_130_dialog_content = "Jangan khawatir, gadis kecil. Dia tidak kecewa atau apa, dia hanya... punya urusan lain.",
  ui_story_31120101_131_dialog_content = "Sepertinya kami belum bisa mampir hari ini, maaf.",
  ui_story_31120101_132_dialog_content = "Oh, tidak apa-apa! Smokey memang selalu seperti ini, terutama saat waktunya pergi.",
  ui_story_31120101_132X_dialog_content = "Kamu akan membantuku mengantarkan bunganya, 'kan?",
  ui_story_31120101_132X1_dialog_content = "Tentu! Jangan khawatir, aku akan cari cara untuk memberikannya kepadanya.",
  ui_story_31120101_132X2_dialog_content = "Dah!",
  ui_story_31120101_133_dialog_content = "Tunggu aku, Smokey!",
  ui_story_31120101_133X_dialog_content = "Bunga ini... Kamu harus menyimpannya.",
  ui_story_31120101_134_dialog_content = "Aku ingin menanyakan sesuatu kepadamu: menurutmu aku kuat?",
  ui_story_31120101_134X_dialog_content = "K-kenapa tiba-tiba kamu menanyakan itu kepadaku?",
  ui_story_31120101_134X1_dialog_content = "Jawab saja pertanyaannya.",
  ui_story_31120101_135_dialog_content = "Ya, kamu kuat. Sangat kuat, jujur saja.",
  ui_story_31120101_136_dialog_content = "Kamu pikir aku juga tidak bisa didekati?",
  ui_story_31120101_137_dialog_content = "Kamu menanyakan ini karena hal itu mengganggumu?",
  ui_story_31120101_138_dialog_content = "Hah, kamu benar-benar mengira aku akan terganggu oleh itu? Kalau begitu, kuberi tahu, ya...",
  ui_story_31120101_139_dialog_content = "*Menghela napas* Bagaimana menurutmu? Panas, ya?",
  ui_story_31120101_140_dialog_content = "N-napasmu... Ini seperti uap! Kenapa begitu panas?",
  ui_story_31120101_141_dialog_content = "Akhir-akhir ini aku merasa aneh...",
  ui_story_31120101_141X_dialog_content = "Sulit bagiku untuk memadamkan api di tubuhku.",
  ui_story_31120101_142_dialog_content = "Jika kamu terlalu dekat denganku, kemungkinan pakaianmu akan terbakar.",
  ui_story_31120101_143_dialog_content = "Apakah itu alasanmu menolak untuk memegang bunga ini?",
  ui_story_31120101_144_dialog_content = "Benar sekali. Ketika kamu mengambil bunga itu kembali, semuanya akan baik-baik saja.",
  ui_story_31120101_144X_dialog_content = "Akhir yang baik bagi semua orang.",
  ui_story_31120101_145_dialog_content = "Ternyata Areia selama ini benar, kamu ADALAH orang yang baik.",
  ui_story_31120101_145X_dialog_content = "Tapi, aku masih ingin meneruskan rencana kami untuk meningkatkan citra dirimu. Aku ingin semua orang mengetahuinya juga...",
  ui_story_31120101_146_dialog_content = "Kembalilah dan beri tahu Areia untuk tidak terlalu mengkhawatirkan citraku. Aku tidak peduli apa yang orang lain pikirkan tentangku.",
  ui_story_31120101_146X_dialog_content = "Itu juga berlaku untukmu. Carilah hal lain untuk dilakukan saat senggang.",
  ui_story_31120101_147_dialog_content = "Tapi, semua orang ternyata salah sangka padamu! Mereka semua mengira kamu adalah orang yang temperamental dan cuek...",
  ui_story_31120101_148_dialog_content = "Baiklah, mereka benar tentang satu hal—aku MEMANG bertemperamen buruk. Selain itu, orang-orang yang seharusnya memahamiku sudah memahamiku.",
  ui_story_31120101_149_dialog_content = "Bisa dibilang \"rencana\" kecilmu berhasil.",
  ui_story_31120101_149X_dialog_content = "Atau apakah citra diriku belum membaik di matamu?",
  ui_story_31120601_1_dialog_content = "(Di langit malam di atas kota...)",
  ui_story_31120601_2_dialog_content = "(Di sana, yang bersinar paling terang melawan kegelapan, bahkan lebih terang dari bintang mana pun di langit... adalah batu permata di tangannya.)",
  ui_story_31120601_3_dialog_content = "(Saya tidak tahu kapan atau bagaimana dia berhasil mencurinya.)",
  ui_story_31120601_4_dialog_content = "(Tapi yang saya tahu, adalah bahwa siapa pun yang melihat apa yang saya lihat akan merasakan hal yang sama seperti saya...)",
  ui_story_31120601_5_dialog_content = "(Seolah-olah sesuatu yang berharga telah dicuri dari mereka.)",
  ui_story_31120601_6_dialog_content = "<color=#e8d9bb>Sebelumnya hari itu</color>",
  ui_story_31120601_7_dialog_content = "Jadi, dengan kata lain, Anda menerima pekerjaan untuk menjaga batu permata yang berharga.",
  ui_story_31120601_8_dialog_content = "Pemilik batu permata menerima kartu panggil dari pencuri hantu.",
  ui_story_31120601_9_dialog_content = "Dan untuk beberapa alasan... kamu pikir ini ada hubungannya dengan Smokey. Apakah itu benar?",
  ui_story_31120601_10_dialog_content = "Tepat! Aku seharusnya tahu dia akan berjalan di jalan kejahatan cepat atau lambat...",
  ui_story_31120601_11_dialog_content = "Kali ini, aku bersumpah aku tidak akan membiarkan dia lolos begitu saja!",
  ui_story_31120601_12_dialog_content = "Aku akan mengikatnya, bagus dan kencang, dan membuatnya menangis dan memohon belas kasihan tepat di kakiku!",
  ui_story_31120601_13_dialog_content = "Ada satu hal yang saya tidak mengerti, meskipun.",
  ui_story_31120601_14_dialog_content = "Anda belum bertemu klien Anda, kan? Bagaimana Anda bisa begitu yakin? Smokeyterlibat?",
  ui_story_31120601_15_dialog_content = "Sebut saja itu intuisi wanita.",
  ui_story_31120601_16_dialog_content = "Itu dia?",
  ui_story_31120601_17_dialog_content = "Ini sesederhana itu.",
  ui_story_31120601_18_dialog_content = "Percayalah, ketika harus berburu Smokey...",
  ui_story_31120601_19_dialog_content = "Intuisiku jauh lebih tajam daripada kemampuan psikis seorang Caelestite!",
  ui_story_31120601_20_dialog_content = "Begitu... Jadi apa hubungannya semua ini denganku?",
  ui_story_31120601_21_dialog_content = "Untuk menjalankan rencanaku yang sempurna untuk menahan dan menahan Smokey, Anda akan memainkan peran yang paling penting, Tuan Navigator!",
  ui_story_31120601_22_dialog_content = "Sekarang ayo pergi! Waktu yang disebutkan di kartu panggil semakin dekat.",
  ui_story_31120601_23_dialog_content = "Tentu, tapi... Apa menurutmu setidaknya kau bisa mengendurkan cambukmu dulu? Aku benar-benar tidak bisa bergerak...",
  ui_story_31120601_24_dialog_content = "Saya minta maaf, tetapi untuk memastikan eksekusi sempurna rencana saya yang sempurna, Anda harus menanggungnya sedikit lebih lama.",
  ui_story_31120601_25_dialog_content = "...",
  ui_story_31120601_26_dialog_content = "Anda di sini akhirnya, nyonya! Silakan, masuk!",
  ui_story_31120601_27_dialog_content = "Er, dan pria menawan yang tertangkap cambukmu ini akan...",
  ui_story_31120601_28_dialog_content = "Ah ya, ini Pak Navigator. Dia akan menjadi asisten saya hari ini.",
  ui_story_31120601_29_dialog_content = "<color=#e8d9bb>Suara mendesing!</color>",
  ui_story_31120601_30_dialog_content = "Wah...akhirnya bisa bernafas lagi...",
  ui_story_31120601_31_dialog_content = "Tn. Navigator, izinkan saya memperkenalkan Anda pada penilai permata terkenal yang saya sebutkan sebelumnya.",
  ui_story_31120601_32_dialog_content = "Dia juga kebetulan menjadi klien untuk tugas saya saat ini.",
  ui_story_31120601_33_dialog_content = "Halo...",
  ui_story_31120601_34_dialog_content = "Astaga. Apakah situasinya begitu parah sehingga memerlukan bantuan bukan hanya satu, tetapi dua spesialis? Tampaknya pencuri hantu ini tidak bisa dianggap enteng...",
  ui_story_31120601_35_dialog_content = "Yakinlah, tuan yang baik. Dengan saya dalam kasus ini, pencuri tidak akan pernah berhasil.",
  ui_story_31120601_36_dialog_content = "Sekarang, bisa tolong tunjukkan kartu panggil pencuri itu?",
  ui_story_31120601_37_dialog_content = "T-Mereka semua pergi...",
  ui_story_31120601_38_dialog_content = "Hilang? Maksud kamu apa?",
  ui_story_31120601_39_dialog_content = "Saya menerima kartu panggil pertama sepuluh hari yang lalu.",
  ui_story_31120601_40_dialog_content = "Namun, cerita tentang pencuri hantu telah menjadi perbincangan di Umbraton akhir-akhir ini.",
  ui_story_31120601_41_dialog_content = "Anak-anak dari rumah tanpa uang telah mengidolakan pencuri dalam cerita ini dan meninggalkan kartu panggil sebagai lelucon",
  ui_story_31120601_42_dialog_content = "daripada menghabiskan waktu mereka untuk perbuatan yang lebih baik.",
  ui_story_31120601_43_dialog_content = "Semua orang di jalan ini yang memiliki sesuatu untuk mereka telah menerima setidaknya satu kartu yang dibuat dengan kasar dari anak-anak nakal itu.",
  ui_story_31120601_44_dialog_content = "Tapi sama menyebalkannya dengan mereka, anak-anak hanya bermain-main. Mereka tidak cukup berani untuk benar-benar mengambil tindakan.",
  ui_story_31120601_45_dialog_content = "Jadi ketika saya menerima kartu panggil pertama saya, saya menganggapnya sebagai lelucon tanpa berpikir dua kali.",
  ui_story_31120601_46_dialog_content = "Jadi kau membuangnya begitu saja? Itu adalah bukti penting!",
  ui_story_31120601_47_dialog_content = "Ya... Saya memang membuang kartu panggil pertama.",
  ui_story_31120601_48_dialog_content = "Tetapi segera setelah itu, saya menerima satu lagi, diikuti oleh yang lain lagi. Ada total lima kartu panggil, yang semuanya menyebutkan sesuatu tentang hitungan mundur ...",
  ui_story_31120601_49_dialog_content = "Saya memutuskan untuk menyelamatkan mereka dengan tujuan suatu hari menemukan kretin kecil yang membutuhkan sedikit disiplin.",
  ui_story_31120601_50_dialog_content = "Lalu?",
  ui_story_31120601_51_dialog_content = "Dan kemudian... Baru tiga malam yang lalu, tiba-tiba aku melihat bau asap yang menyengat di suatu tempat di kamarku...",
  ui_story_31120601_52_dialog_content = "Saya membuka pintu, hanya untuk menemukan bahwa kotak tempat saya menyimpan kartu panggil telah terbakar!",
  ui_story_31120601_53_dialog_content = "Dan di sana, berdiri di sebelahnya, ada sosok tubuh langsing, yang rambutnya diikat menjadi dua ekor kuda panjang.",
  ui_story_31120601_54_dialog_content = "Smokey... Aku benar, selama ini! Itu harus Smokey!",
  ui_story_31120601_55_dialog_content = "Ah, saya berharap tidak kurang dari pemburu hadiah terkenal seperti Anda! Anda sudah tahu identitas pencuri hantu?",
  ui_story_31120601_56_dialog_content = "Ahem... kita belum bisa memastikannya secara pasti, kan? Apakah Anda pernah berhasil melihat wajah orang itu?",
  ui_story_31120601_57_dialog_content = "Malam itu gelap, jadi aku tidak bisa melihat wajah mereka... Tapi dilihat dari suaranya, aku yakin pencurinya adalah seorang wanita.",
  ui_story_31120601_58_dialog_content = "Dan apa sebenarnya yang dia katakan?",
  ui_story_31120601_59_dialog_content = "Tiga hari dari sekarang, di tengah malam...",
  ui_story_31120601_60_dialog_content = "Aku akan kembali untuk mengambil batu permata.",
  ui_story_31120601_61_dialog_content = "S-Siapa kamu?",
  ui_story_31120601_62_dialog_content = "Saya yakin saya meninggalkan tanda tangan di kartu panggil saya.",
  ui_story_31120601_63_dialog_content = "<color=#FFB400>\"Kucing hitam\"</color>? Tapi itu tidak mungkin nama aslimu, kan?",
  ui_story_31120601_64_dialog_content = "Sebagai tanggapan, dia membuat suara cemoohan yang tidak sabar, dan pada saat berikutnya... dia menghilang tepat di depan mataku, seperti bisikan di angin!",
  ui_story_31120601_65_dialog_content = "Aduh... Saat itulah aku tahu pencuri hantu ini serius.",
  ui_story_31120601_66_dialog_content = "Yah, sikap seperti itu kedengarannya seperti—",
  ui_story_31120601_67_dialog_content = "Smokey!",
  ui_story_31120601_68_dialog_content = "Jika dia berpikir menghancurkan bukti akan membuat saya keluar dari jejaknya, dia punya hal lain yang akan datang.",
  ui_story_31120601_69_dialog_content = "Aku bersumpah, Smokey akan berada di bawah belas kasihan cambuk saya pada akhir hari!",
  ui_story_31120601_69X_dialog_content = "Aku ingin melihat Shadowlord yang gila itu mencoba menyelamatkannya dari amarahku!",
  ui_story_31120601_70_dialog_content = "Namun, tidakkah menurut Anda perilaku ini agak terlalu kurang ajar?",
  ui_story_31120601_71_dialog_content = "Mengirim begitu banyak kartu panggil melalui pos, dan bahkan membobol rumah penilai hanya untuk menghancurkan barang bukti?",
  ui_story_31120601_72_dialog_content = "Bukankah lebih mudah untuk hanya mencuri batu permata?",
  ui_story_31120601_73_dialog_content = "Hmph, itu hanya jenis monster yang tidak berperasaan dan merendahkan dirinya. Dia tidak pernah puas kecuali dia melibatkan sebanyak mungkin orang dalam kenakalannya.",
  ui_story_31120601_74_dialog_content = "K-Kamu benar-benar berpikir begitu?",
  ui_story_31120601_75_dialog_content = "Dia selalu seperti ini.",
  ui_story_31120601_76_dialog_content = "Tapi dia salah besar jika dia pikir dia akan pergi sambil tertawa hari ini!",
  ui_story_31120601_77_dialog_content = "Mendengar Anda mengucapkan kata-kata ini membuat saya lega.",
  ui_story_31120601_78_dialog_content = "Lihat, ini batu permata yang diincar si pencuri hantu.",
  ui_story_31120601_79_dialog_content = "Wow... Berlian yang sangat indah!",
  ui_story_31120601_80_dialog_content = "Ha ha ha! Sayangnya, ini bukan berlian belaka!",
  ui_story_31120601_81_dialog_content = "Ini lebih keras daripada berlian mana pun, lebih tahan lama daripada emas, dan lebih terang dari aurora Northland. Ini adalah batu permata paling berharga yang ada saat ini.",
  ui_story_31120601_82_dialog_content = "Hanya ada satu dari jenisnya di seluruh dunia.",
  ui_story_31120601_83_dialog_content = "Begitu... Tidak heran pencuri hantu mengejarnya.",
  ui_story_31120601_84_dialog_content = "Aku sedang berpikir untuk diriku sendiri sekarang, dengan semua permata berharga di rumahmu...",
  ui_story_31120601_85_dialog_content = "Mengapa Anda begitu yakin bahwa pencuri hantu itu menargetkan yang satu ini?",
  ui_story_31120601_86_dialog_content = "...",
  ui_story_31120601_87_dialog_content = "Tampaknya nilai total dari semua bagian lain dalam koleksi Anda tidak akan mendekati nilai batu permata ini.",
  ui_story_31120601_88_dialog_content = "Ya, ya, itu saja.",
  ui_story_31120601_89_dialog_content = "Sekarang, saya akan meninggalkan sisanya di tangan Anda yang cakap!",
  ui_story_31120601_90_dialog_content = "Kita tidak punya banyak waktu lagi, jadi bersiaplah.",
  ui_story_31120601_91_dialog_content = "Saya akan mengatakannya sekali lagi: saat Anda merasakannya Smokey's, Anda harus memberitahu saya persis di mana dia!",
  ui_story_31120601_92_dialog_content = "Tapi bisakah kita benar-benar melakukannya...? Hanya dengan kita berdua?",
  ui_story_31120601_93_dialog_content = "Apakah Anda benar-benar berpikir kita sendirian? Penggemar saya berdiri di luar, siap untuk menyergap Smokey pada waktu tertentu!",
  ui_story_31120601_94_dialog_content = "<color=#e8d9bb>Gong...Gong...Gong...</color>",
  ui_story_31120601_95_dialog_content = "Ini sudah lewat tengah malam... Kenapa dia belum datang?",
  ui_story_31120601_96_dialog_content = "Ssst...",
  ui_story_31120601_97_dialog_content = "Dia disini! Diluar jendela!",
  ui_story_31120601_98_dialog_content = "<color=#e8d9bb>*kaca pecah*</color>",
  ui_story_31120601_98X_dialog_content = "Smokey! Jangan berpikir Anda bisa menerobos dan masuk begitu saja!",
  ui_story_31120601_99_dialog_content = "Sepertinya penggemarmu tidak bisa menghentikan pencurinya...",
  ui_story_31120601_100_dialog_content = "Hmm... Apa yang terjadi? Tidak ada orang di luar jendela sama sekali!",
  ui_story_31120601_101_dialog_content = "Hah? L-Biarkan aku mencoba lagi.",
  ui_story_31120601_102_option_content = "Gunakan kemampuan psikis",
  ui_story_31120601_103_dialog_content = "Oh, tidak... Pencurinya sudah di depan pintu!",
  ui_story_31120601_103X_dialog_content = "Lalu apa gunanya memecahkan jendela tadi...?",
  ui_story_31120601_104_dialog_content = "Pengalih perhatian... mungkin? Aku akan berdiri di dekat pintu! Mari kita lihat dia melewatiku sekarang!",
  ui_story_31120601_105_dialog_content = "<color=#e8d9bb>Bang!</color>",
  ui_story_31120601_106_dialog_content = "Ah!",
  ui_story_31120601_107_dialog_content = "Genevieve! Apakah ... Apakah Anda baik-baik saja?",
  ui_story_31120601_108_dialog_content = "Minggir, PlayerName!",
  ui_story_31120601_109_dialog_content = "Rasakan ini! Terbakar!",
  ui_story_31120601_110_dialog_content = "Ha! Bakar, sayang, bakar!",
  ui_story_31120601_111_dialog_content = "Hampir saja! Aku hampir hangus. Tapi serangan itu barusan...",
  ui_story_31120601_112_dialog_content = "Smokey... Aku tahu itu kamu selama ini!",
  ui_story_31120601_113_dialog_content = "Haha, di sini lebih hidup dari yang kukira.",
  ui_story_31120601_114_dialog_content = "Bahkan Anda memutuskan untuk ikut bersenang-senang, PlayerName?",
  ui_story_31120601_115_option_content = "Ya...",
  ui_story_31120601_116_dialog_content = "Lebih tepatnya, saya agak terseret ke dalamnya.",
  ui_story_31120601_117_option_content = "Tolong jangan salah paham...",
  ui_story_31120601_118_dialog_content = "Aku benar-benar tidak punya pilihan...",
  ui_story_31120601_119_dialog_content = "Hal-hal menjadi menarik!",
  ui_story_31120601_120_dialog_content = "Hai! Beraninya kau mengabaikanku!",
  ui_story_31120601_121_dialog_content = "Membakar!",
  ui_story_31120601_122_dialog_content = "Tetap di bawah!",
  ui_story_31120601_123_dialog_content = "Sejujurnya... Aku tidak pernah menyangka kau akan mengejarku sampai ke sini, Ginny.",
  ui_story_31120601_124_dialog_content = "G-Ginny?",
  ui_story_31120601_125_dialog_content = "Siapa bilang kamu bisa memanggilku begitu?!",
  ui_story_31120601_126_dialog_content = "Astaga, keberatan menyimpannya? Suaramu membuatku sakit kepala.",
  ui_story_31120601_127_dialog_content = "Lagipula, bukan salahku namamu begitu panjang. Saya hanya tidak ingin mengatakan semuanya setiap saat.",
  ui_story_31120601_128_dialog_content = "Jadi, orang-orang lemah di luar... Apakah kamu meninggalkan mereka di luar sana untukku, supaya aku bisa mendapatkan pemanasan yang bagus?",
  ui_story_31120601_129_dialog_content = "Ginny-viese?",
  ui_story_31120601_130_dialog_content = "Dia Genevieve!!!",
  ui_story_31120601_131_dialog_content = "Apakah Anda mencoba meniru serangan saya?",
  ui_story_31120601_132_dialog_content = "kamu bercanda kan? Apakah Anda lupa bahwa bakat saya untuk Luminatics terwujud lebih dulu?",
  ui_story_31120601_133_dialog_content = "Oh? Seperti itukah yang terjadi?",
  ui_story_31120601_134_dialog_content = "Smokey terus menghindari semua Genevieveserangannya di saat yang tepat...",
  ui_story_31120601_135_dialog_content = "Dan sementara itu, dia terus semakin dekat dengan etalase batu permata!",
  ui_story_31120601_136_dialog_content = "Bahkan tidak memikirkannya!!!",
  ui_story_31120601_137_dialog_content = "Bagaimana kalau Anda mencoba menghentikan saya?",
  ui_story_31120601_138_dialog_content = "Kenapa kamu harus seperti ini...",
  ui_story_31120601_139_dialog_content = "Mengapa Anda bersikeras pada perilaku kriminal yang sembrono ini?!",
  ui_story_31120601_140_dialog_content = "Mengapa Anda juga suka ikut campur dalam urusan orang lain?",
  ui_story_31120601_141_dialog_content = "K-Kamu pikir aku hanya ikut campur?! Aku selalu... Aku selalu memandangmu sebagai seseorang yang harus dilampaui suatu hari nanti...",
  ui_story_31120601_142_dialog_content = "Tapi lihatlah kamu telah menjadi apa!",
  ui_story_31120601_143_dialog_content = "kamu bukan Smokey Dulu aku tahu... Tidak lagi.",
  ui_story_31120601_144_dialog_content = "Oi, mungkin saya lupa menyebutkannya, tapi saya \"Kucing Hitam\" hari ini, bukan Smokey.",
  ui_story_31120601_145_dialog_content = "Jika memang begitu... Maka aku tidak punya alasan untuk menahan diri.",
  ui_story_31120601_146_dialog_content = "Menyerah!",
  ui_story_31120601_147_dialog_content = "<color=#e8d9bb>Ledakan!</color>",
  ui_story_31120601_148_dialog_content = "A-Sungguh api yang sangat besar!",
  ui_story_31120601_149_dialog_content = "Batu permata saya...",
  ui_story_31120601_150_dialog_content = "Jangan khawatir, saya selangkah lebih maju darinya dan berhasil meraih batu permata Anda di depannya.",
  ui_story_31120601_151_dialog_content = "Melihat-",
  ui_story_31120601_152_dialog_content = "T-Tunggu... Genevieve, apakah kamu membakar batu permata itu?!",
  ui_story_31120601_153_dialog_content = "Apa yang telah kamu lakukan, bodoh?! Aku mempekerjakanmu untuk melindungi batu itu, bukan menghancurkannya!",
  ui_story_31120601_154_dialog_content = "SAYA...",
  ui_story_31120601_155_dialog_content = "Maaf saya...",
  ui_story_31120601_156_dialog_content = "Hahaha, menarik.",
  ui_story_31120601_157_dialog_content = "Sudah lama aku tidak bersenang-senang seperti ini.",
  ui_story_31120601_158_dialog_content = "Smokey! Apakah ini salah satu trikmu?!",
  ui_story_31120601_159_dialog_content = "Anda orang masih tidak mengerti? Batu yang kau ubah menjadi abu bahkan bukan yang asli.",
  ui_story_31120601_160_dialog_content = "K-Kamu pembohong!",
  ui_story_31120601_161_dialog_content = "Itu adalah milikku yang paling langka dan paling berharga!",
  ui_story_31120601_162_dialog_content = "Oh, benar-benar sekarang.",
  ui_story_31120601_163_dialog_content = "Batu permata yang kamu curi tidak akan mudah terbakar, setuju kan?",
  ui_story_31120601_164_dialog_content = "\"Mencuri\"? Apa yang kau bicarakan?",
  ui_story_31120601_165_dialog_content = "Pemilik sebenarnya dari batu permata ini bukanlah orang ini di sini.",
  ui_story_31120601_166_dialog_content = "Serahkan!",
  ui_story_31120601_167_dialog_content = "Tolong... Anda tidak bisa... Tolong jangan ambil batu permata ini dari saya! Hanya itu yang tersisa untuk mengingat ibuku dengan...",
  ui_story_31120601_168_dialog_content = "Sesuatu seperti ini tidak akan pernah memiliki nilai di tanganmu seperti milikmu, nak.",
  ui_story_31120601_169_dialog_content = "Yakinlah, aku akan menjaganya dengan sangat baik.",
  ui_story_31120601_171_dialog_content = "... Perhatikan, Nak.",
  ui_story_31120601_172_dialog_content = "Hei, mari kita dengarkan cerita nenek lainnya!",
  ui_story_31120601_172X_dialog_content = "Saya mendengar mereka akan berbicara tentang pencuri hantu hari ini!",
  ui_story_31120601_172X1_dialog_content = "Hmm? Apa yang dibicarakan kedua anak itu?",
  ui_story_31120601_173_dialog_content = "Anda pergi ke depan ... Saya akan menyusul semua orang sebentar lagi.",
  ui_story_31120601_174_dialog_content = "Jangan terlalu lama!",
  ui_story_31120601_175_dialog_content = "Pencuri hantu... Andai saja mereka nyata...",
  ui_story_31120601_176_dialog_content = "Maka mungkin salah satu dari mereka bisa membantuku mengambil kembali batu permata yang ditinggalkan ibuku... Kalau saja...",
  ui_story_31120601_177_dialog_content = "Pencuri hantu, ya?",
  ui_story_31120601_178_dialog_content = "Kedengarannya cukup menarik.",
  ui_story_31120601_179_dialog_content = "Tunggu, jadi kalian tidak tahu?",
  ui_story_31120601_180_dialog_content = "Dan di sini saya pikir Anda setidaknya telah melihat kartu panggil yang saya kirim.",
  ui_story_31120601_181_dialog_content = "Saya menyebutkan bahwa jika batu itu diberikan kembali kepada anak itu, saya tidak perlu datang ke sini secara pribadi untuk itu.",
  ui_story_31120601_182_dialog_content = "Tapi apakah Anda tidak membakar kartu panggil?",
  ui_story_31120601_183_dialog_content = "Hah? Jangan kambing hitam saya untuk hal-hal yang tidak saya lakukan.",
  ui_story_31120601_184_dialog_content = "Maka itu hanya menyisakan satu kemungkinan lain ...",
  ui_story_31120601_185_dialog_content = "Tuan Penilai, Anda membakarnya, bukan?",
  ui_story_31120601_186_dialog_content = "B-Bukti apa yang kamu miliki?",
  ui_story_31120601_187_dialog_content = "... Tidak ada saat ini, sayangnya.",
  ui_story_31120601_188_dialog_content = "Tapi siapa pun yang membakar mereka pasti melakukannya untuk menutupi kejahatan mereka.",
  ui_story_31120601_189_dialog_content = "Kita selalu bisa mencari anak itu dan menanyakan apakah dia kehilangan batu permata...",
  ui_story_31120601_190_dialog_content = "Ha ha ha ha! Saya mengerti sekarang!",
  ui_story_31120601_191_dialog_content = "Kalian berdua bajingan telah berkolusi dengan \"Kucing Hitam\" ini, bukan?!",
  ui_story_31120601_192_dialog_content = "Sekarang setelah Anda menghancurkannya, bagaimana Anda berencana membayar saya untuk itu?!",
  ui_story_31120601_193_dialog_content = "Ugh, sungguh menyebalkan... Aku benci saat orang merinding sepertimu menolak untuk mengaku kalah.",
  ui_story_31120601_194_dialog_content = "Anda takut saya akan mencuri batu permata asli, jadi Anda menggantinya dengan yang palsu.",
  ui_story_31120601_195_dialog_content = "Dengan begitu, jika yang palsu dicuri, dia tidak akan kehilangan sesuatu yang berharga.",
  ui_story_31120601_196_dialog_content = "Dan jika itu dihancurkan karena suatu alasan, dia bisa menyalahkan kita.",
  ui_story_31120601_197_dialog_content = "Ha, rencana yang disusun dengan cermat.",
  ui_story_31120601_198_dialog_content = "Berbohong! Kebohongan dan fitnah!",
  ui_story_31120601_199_dialog_content = "Jika Anda masih tidak mau berterus terang, bagaimana kalau kita membayar Istvan Geng kunjungan bersama?",
  ui_story_31120601_200_dialog_content = "Istvan...",
  ui_story_31120601_201_dialog_content = "Orang-orang Umbraton semua mengatakan bahwa dia baik dengan hal-hal semacam ini.",
  ui_story_31120601_202_dialog_content = "Ah, tapi Anda akan tahu lebih baik dari saya, kan? Lagi pula, Anda juga penduduk Umbraton.",
  ui_story_31120601_203_dialog_content = "...",
  ui_story_31120601_204_dialog_content = "Di mana Anda menyembunyikan batu permata asli?",
  ui_story_31120601_205_dialog_content = "...!",
  ui_story_31120601_206_dialog_content = "Itu... Hilang!!!",
  ui_story_31120601_207_dialog_content = "Cukup trik Anda! Beritahu kami di mana itu!",
  ui_story_31120601_208_dialog_content = "Aku... Aku mengatakan yang sebenarnya! Itu ada di sakuku selama ini... Tapi sekarang aku tidak menemukannya!",
  ui_story_31120601_209_dialog_content = "Muntahkan!",
  ui_story_31120601_210_dialog_content = "Dimana batu permata yang asli, pencuri?!",
  ui_story_31120601_211_dialog_content = "Oh, berhenti membuang-buang napas padanya.",
  ui_story_31120601_212_dialog_content = "Smokey...",
  ui_story_31120601_213_dialog_content = "Tunggu, kemana dia pergi?!",
  ui_story_31120601_214_dialog_content = "dia...",
  ui_story_31120601_215_dialog_content = "Dia di sebelah sana! Di atap di seberang kami!",
  ui_story_31120601_216_dialog_content = "Tapi bagaimana caranya? Dia ada di kamar beberapa saat yang lalu...",
  ui_story_31120601_217_dialog_content = "Mengapa Anda begitu terkejut?",
  ui_story_31120601_218_dialog_content = "Aku mengerti.",
  ui_story_31120601_219_dialog_content = "Anda tidak memiliki rasa imajinasi, itu sebabnya Anda tidak dapat memahaminya.",
  ui_story_31120601_220_dialog_content = "Beraninya kau mengejekku lagi?!",
  ui_story_31120601_221_dialog_content = "Ini hanya fakta.",
  ui_story_31120601_222_dialog_content = "Tunggu, apakah itu... batu permata asli di tanganmu?!",
  ui_story_31120601_223_dialog_content = "Butuh waktu lama bagimu untuk menyadarinya.",
  ui_story_31120601_224_dialog_content = "Astaga, ini membosankan.",
  ui_story_31120601_225_dialog_content = "Aku keluar dari sini, dan aku membawa ini bersamaku.",
  ui_story_31120601_226_dialog_content = "Sampai jumpa lain waktu.",
  ui_story_31120601_227_dialog_content = "<size=50>T-Tunggu!!!</size>",
  ui_story_31120601_228_dialog_content = "<color=#e8d9bb>Suara mendesing--</color>",
  ui_story_31120601_229_dialog_content = "Dia pergi...",
  ui_story_31120601_230_dialog_content = "...",
  ui_story_31120601_231_dialog_content = "Mengapa saya merasa begitu kosong, tiba-tiba?",
  ui_story_31120601_232_dialog_content = "...",
  ui_story_31120601_233_dialog_content = "Apa yang harus kita lakukan sekarang?",
  ui_story_31120601_234_dialog_content = "Bawa pelaku ke pengadilan, tentu saja.",
  ui_story_31120601_235_dialog_content = "Tetapi Smokeysudah lama berlalu...",
  ui_story_31120601_236_dialog_content = "Aku sedang berbicara tentang penilai permata. Apapun yang terjadi selanjutnya adalah untuk Istvan Geng untuk memutuskan.",
  ui_story_31120601_237_dialog_content = "Tapi batu permata...",
  ui_story_31120601_238_dialog_content = "Saya membayangkan Smokey menyerahkannya kembali kepada anak itu.",
  ui_story_31120601_239_dialog_content = "Yo nak, aku punya sesuatu untukmu.",
  ui_story_31120601_240_dialog_content = "M-Batu permataku... Kamu menemukannya!!",
  ui_story_31120601_241_dialog_content = "Entah bagaimana aku merasa kamu masih percaya Smokey, Genevieve.",
  ui_story_31120601_242_dialog_content = "Jangan salah paham!",
  ui_story_31120601_243_dialog_content = "Suatu hari nanti, aku bersumpah akan menangkapnya saat beraksi! Lalu, aku akan mengikatnya, bagus dan kencang...",
  ui_story_31120601_244_dialog_content = "Dan buat dia menangis dan memohon belas kasihan tepat di kakiku!",
  ui_story_31120601_245_dialog_content = "Acho!",
  ui_story_31120601_246_dialog_content = "Huh... Kurasa cukup mudah masuk angin dengan pakaian ini."
}
return config
